export interface Card {
  monster: string;
}

const isSphinx = (card: Card): boolean => card.monster === "sphinx";

/** A Sphinx scores 1 for itself, plus 1 per other monster type beyond three.
 *  No army tested so far exceeds three types, so the second term is always 1. */
const POINTS_PER_SPHINX_SO_FAR = 2;

export const scoreArmy = (army: Card[]): number =>
  army.filter(isSphinx).length * POINTS_PER_SPHINX_SO_FAR;

