export interface Card {
  monster: string;
}

const isSphinx = (card: Card): boolean => card.monster === "sphinx";

const otherTypeCount = (army: Card[]): number =>
  new Set(army.filter((card) => !isSphinx(card)).map((card) => card.monster))
    .size;

export const scoreArmy = (army: Card[]): number => {
  const sphinxCount = army.filter(isSphinx).length;
  const others = otherTypeCount(army);
  return sphinxCount * (1 + (others > 3 ? 2 * (others - 3) : 1));
};

