export interface Card {
  monster: string;
  rank?: number;
}

const isSphinx = (card: Card): boolean => card.monster === "sphinx";

const TYPE_THRESHOLD = 3;
const POINTS_PER_SPHINX = 1;
const POINTS_WITHIN_THRESHOLD = 1;
const POINTS_PER_TYPE_BEYOND_THRESHOLD = 2;

const countDistinctNonSphinxTypes = (army: Card[]): number =>
  new Set(army.filter((card) => !isSphinx(card)).map((card) => card.monster))
    .size;

const varietyPoints = (typeCount: number): number =>
  typeCount > TYPE_THRESHOLD
    ? POINTS_PER_TYPE_BEYOND_THRESHOLD * (typeCount - TYPE_THRESHOLD)
    : POINTS_WITHIN_THRESHOLD;

const scoreOneSphinx = (typesSeenBySphinx: number): number =>
  POINTS_PER_SPHINX + varietyPoints(typesSeenBySphinx);

export const scoreArmy = (army: Card[]): number => {
  const sphinxCount = army.filter(isSphinx).length;
  const typesSeenBySphinx = countDistinctNonSphinxTypes(army);
  return sphinxCount * scoreOneSphinx(typesSeenBySphinx);
};

